#!/usr/bin/env python3
"""Reproduce 2024 ACS state+US Rent Squeeze extract from official Census files.
Run with Python 3. Downloads only public aggregate data, no credentials.
"""
import csv,json,math,hashlib,pathlib,urllib.request,datetime
ROOT=pathlib.Path(__file__).resolve().parent
BASE='https://www2.census.gov/programs-surveys/acs/summary_file/2024/table-based-SF/'
TABLES=['B25064','B25070','B25119','B25106','B19013','B01003']
SOURCES={t:BASE+'data/1YRData/acsdt1y2024-'+t.lower()+'.dat' for t in TABLES}
SOURCES['geographies']=BASE+'documentation/Geos20241YR.txt'
for t,u in SOURCES.items():
 p=ROOT/('geographies.txt' if t=='geographies' else t+'.dat')
 if not p.exists(): p.write_bytes(urllib.request.urlopen(u,timeout=60).read())
geo=list(csv.DictReader((ROOT/'geographies.txt').open(),delimiter='|'))
selected=[g for g in geo if g['COMPONENT']=='00' and ((g['SUMLEVEL']=='040' and g['STATE']!='72') or g['GEO_ID']=='0100000US')]
assert len(selected)==52,(len(selected),[g['NAME'] for g in selected])
data={}
for t in TABLES:
 rows=list(csv.DictReader((ROOT/(t+'.dat')).open(),delimiter='|'))
 assert len({r['GEO_ID'] for r in rows})==len(rows),t
 data[t]={r['GEO_ID']:r for r in rows}

def val(t,g,n,kind='E'):
 s=data[t][g][f'{t}_{kind}{n:03d}']
 return int(s) if s else None

def metric(e,m):
 return {'estimate':e,'moe':m,'lower90':max(0,e-m),'upper90':e+m,'moeType':'published'}

def prop(n,nm,d,dm):
 p=n/d
 rad=nm*nm-p*p*dm*dm
 fallback=rad<0
 m=100*math.sqrt(nm*nm+p*p*dm*dm if fallback else rad)/d
 e=100*p
 return {'estimate':e,'moe':m,'lower90':max(0,e-m),'upper90':min(100,e+m),'moeType':'approximate-derived','moeFormula':'ratio' if fallback else 'subset-proportion','numerator':n,'numeratorMoe':nm,'denominator':d,'denominatorMoe':dm}

rows=[]
rawrows=[]
checks={'nRows':len(selected),'stateRows':51,'nationalRows':1,'duplicateKeys':0,'missingValues':[],'unexpectedNegativeValues':[],'reconciliationFailures':[]}
labels=['Under $20k','$20k–$34,999','$35k–$49,999','$50k–$74,999','$75k+']
for geo in selected:
 g=geo['GEO_ID']
 raw={'geoid':g,'name':geo['NAME'],'abbr':geo['STUSAB'],'stateFips':geo['STATE'],'tables':{t:data[t][g] for t in TABLES}}
 rawrows.append(raw)
 for t,ds in raw['tables'].items():
  for k,s in ds.items():
   if k=='GEO_ID':continue
   if s=='':checks['missingValues'].append([g,k])
   elif int(s)<0 and not (t=='B01003' and k=='B01003_M001' and s=='-555555555'):
    checks['unexpectedNegativeValues'].append([g,k,s])
 total=val('B25070',g,1);totalM=val('B25070',g,1,'M')
 nc=val('B25070',g,11);ncM=val('B25070',g,11,'M')
 den=total-nc; denM=math.hypot(totalM,ncM)
 n30=sum(val('B25070',g,n) for n in range(7,11));m30=math.sqrt(sum(val('B25070',g,n,'M')**2 for n in range(7,11)))
 n50=val('B25070',g,10);m50=val('B25070',g,10,'M')
 income=[]
 for label,i in zip(labels,[25,29,33,37,41]):
  d=val('B25106',g,i); dm=val('B25106',g,i,'M')
  b=val('B25106',g,i+3); bm=val('B25106',g,i+3,'M')
  bins=[{'label':label2,**metric(val('B25106',g,j),val('B25106',g,j,'M'))} for label2,j in [('Under 20%',i+1),('20–29%',i+2),('30%+',i+3)]]
  income.append({'label':label,'total':metric(d,dm),'burden30Count':metric(b,bm),'burden30Pct':prop(b,bm,d,dm),'distribution':bins,'denominatorDefinition':'Cash-rent renter households with positive income in this income band; excludes no-cash-rent and zero/negative-income categories.'})
  if sum(x['estimate'] for x in bins)!=d:checks['reconciliationFailures'].append([g,'band',i])
 if den!=sum(x['total']['estimate'] for x in income):checks['reconciliationFailures'].append([g,'denominator'])
 if n30!=sum(x['burden30Count']['estimate'] for x in income):checks['reconciliationFailures'].append([g,'burden30'])
 if total!=val('B25106',g,24):checks['reconciliationFailures'].append([g,'rentersTotal'])
 if nc!=val('B25106',g,45)+val('B25106',g,46):checks['reconciliationFailures'].append([g,'notComputed'])
 rows.append({'geoid':g,'name':geo['NAME'],'abbr':geo['STUSAB'],'stateFips':geo['STATE'] or None,'year':2024,'geographyType':'nation' if geo['SUMLEVEL']=='010' else 'state','rent':metric(val('B25064',g,1),val('B25064',g,1,'M')),'renterIncome':metric(val('B25119',g,3),val('B25119',g,3,'M')),'householdIncome':metric(val('B19013',g,1),val('B19013',g,1,'M')),'renters':metric(total,totalM),'population':{'estimate':val('B01003',g,1),'moe':None,'annotation':'Controlled estimate; published MOE -555555555 means no sampling error, not missing population.'},'burden30':prop(n30,m30,den,denM),'burden50':prop(n50,m50,den,denM),'computedRenters':{'estimate':den,'moe':denM,'moeType':'approximate-derived'},'notComputed':metric(nc,ncM),'notComputedPct':100*nc/total,'noCashRent':metric(val('B25106',g,46),val('B25106',g,46,'M')),'zeroOrNegativeIncome':metric(val('B25106',g,45),val('B25106',g,45,'M')),'incomeBands':income})
assert not checks['missingValues'],checks
assert not checks['unexpectedNegativeValues'],checks
assert not checks['reconciliationFailures'],checks
out={'metadata':{'title':'The Rent Squeeze','source':'U.S. Census Bureau, 2024 ACS 1-year Detailed Tables','year':2024,'period':'January–December 2024','retrieved':'2026-10-09','grain':'50 states + District of Columbia; U.S. benchmark separate','dollars':'2024 USD','interval':'90% confidence interval; published MOEs for counts and medians, approximate derived MOEs for percentages','primaryDenominator':'Renter-occupied housing units with computable gross-rent-to-income ratio, excluding no cash rent and zero/negative household income.','sourceUrls':SOURCES,'license':'CC0 1.0','licenseEvidence':'https://catalog.data.gov/dataset/acs-1-year-detailed-tables-d0fe5','licenseUrl':'https://creativecommons.org/publicdomain/zero/1.0/'},'national':next(r for r in rows if r['geographyType']=='nation'),'states':sorted([r for r in rows if r['geographyType']=='state'],key=lambda r:r['name']),'checks':checks}
(ROOT/'rent-squeeze-2024.json').write_text(json.dumps(out,indent=2))
(ROOT/'rent-squeeze-raw-selected.json').write_text(json.dumps(rawrows,indent=2))
manifest=[]
for t,u in SOURCES.items():
 p=ROOT/('geographies.txt' if t=='geographies' else t+'.dat')
 manifest.append({'sourceId':t,'url':u,'path':p.name,'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'retrieved':'2026-10-09'})
(ROOT/'source-manifest.json').write_text(json.dumps(manifest,indent=2))
with (ROOT/'rent-squeeze-2024.csv').open('w') as f:
 fields=['geoid','name','abbr','year','rent','rent_moe','renter_income','renter_income_moe','burden30_pct','burden30_moe_approx','burden50_pct','burden50_moe_approx','renters','computed_renters','not_computed','not_computed_pct']
 w=csv.DictWriter(f,fields);w.writeheader()
 for r in rows:w.writerow({'geoid':r['geoid'],'name':r['name'],'abbr':r['abbr'],'year':2024,'rent':r['rent']['estimate'],'rent_moe':r['rent']['moe'],'renter_income':r['renterIncome']['estimate'],'renter_income_moe':r['renterIncome']['moe'],'burden30_pct':r['burden30']['estimate'],'burden30_moe_approx':r['burden30']['moe'],'burden50_pct':r['burden50']['estimate'],'burden50_moe_approx':r['burden50']['moe'],'renters':r['renters']['estimate'],'computed_renters':r['computedRenters']['estimate'],'not_computed':r['notComputed']['estimate'],'not_computed_pct':r['notComputedPct']})
print(json.dumps(checks))
print('National:',json.dumps({k:out['national'][k] for k in ['rent','renterIncome','burden30','burden50','notComputedPct']}))
print('Saved',ROOT/'rent-squeeze-2024.json')

